/* NEX-7 Creative Style -> Picture Profile recipe hook.
 *
 * Active only in im.elf (which loads libObj) and its descendants. Other processes
 * get a plain osal_snd_msg pass-through. Configuration is a validated 164-byte
 * /setting/nexhook-recipes.bin generated by scripts/recipe_config.py.
 *
 * 0x4039: send a cloned stock 0x400c WB message when configured, then apply the
 *         configured base Creative Style and a 39-byte 0x4066 recipe profile.
 * 0x4066: rewrite all 31 values from the neutral PP1 baseline + configured four,
 *         so later app re-sends cannot silently restore a different recipe.
 * 0x400c / aggregate 0x397: clone valid stock WB templates and rewrite only the
 *         configured WB mode (and C6 Kelvin) after the generation guard passes.
 *
 * All allocations use osal_valloc_msg_wait; no asynchronous stack/static messages.
 * Missing config, invalid state, unavailable APIs, or a tripped boot crash guard
 * disable modification. The crash guard generation is the 36-byte kernel boot
 * UUID plus the latest little-endian WARM count from /proc/snsc_boot_time.
 * Raw syscalls only for files/logging; dlsym resolves OSAL.
 */

#define O_WRONLY 01
#define O_RDWR 02
#define O_CREAT 0100
#define O_EXCL 0200
#define O_APPEND 02000
#define SEEK_SET 0
#define SEEK_END 2

#define SYS_read 3
#define SYS_write 4
#define SYS_open 5
#define SYS_close 6
#define SYS_unlink 10
#define SYS_getpid 20
#define SYS_lseek 19
#define SYS_rename 38       /* Linux ARM EABI */
#define SYS_flock 143       /* Linux ARM EABI */
#define SYS_clock_gettime 263

#define CAMERA_CORE_MAILBOX 0x00030001UL
#define MSG_COLOR_MODE 0x4039
#define MSG_PICTURE_PROFILE 0x4066
#define MSG_WB_MODE_CMD 0x400c
#define MSG_INIT_SETTINGS 0x0397
#define WB_MESSAGE_SIZE 13
#define WB_INIT_OFFSET 0x2c
#define PROFILE_SIZE 39
#define PROFILE_VALUES 31
#define CONFIG_SIZE 164
#define CONFIG_STYLES 16
#define GENERATION_SIZE 40
#define BOOT_ID_SIZE 36
#define LOG_MAX 16384
#define ACTION_LOG_MAX 128
#define GUARD_CLEAR_SECONDS 60
#define GUARD_DISARM 5
#define LOCK_EX 2
#define ENOENT 2
#define EEXIST 17
#define RTLD_NEXT ((void *)-1L)

#define CONFIG_PATH "/setting/nexhook-recipes.bin"
#define GUARD_PATH "/setting/nexhook.bootcount"
#define GUARD_GEN_PATH "/tmp/nexhook.guardgen"
#define GUARD_LOCK_PATH "/tmp/nexhook.guard.lock"
#define STATE_PATH "/tmp/nexhook-style.state"
#define LOG_PATH "/setting/nexhook-recipe.log"
#define BOOT_ID_PATH "/proc/sys/kernel/random/boot_id"
#define BOOT_LOG_PATH "/proc/snsc_boot_time"

