#define WB_STORE_MODE 0x01070019UL
#define WB_STORE_ADJUST_LB 0x01070017UL
#define WB_STORE_ADJUST_CC 0x01070016UL
#define WB_STORE_COLOR_TEMP 0x01070018UL
#define WB_STORE_DAYLIGHT_LEVEL 0x0107035dUL

#define STATE_UNKNOWN 0xfe
#define STATE_DISARMED 0xff

