static int atomic_write_file(const char *path, const void *data, long size)
{
    char temp[128];
    long fd = -1;
    long done = 0;
    int attempt, n;

    for (attempt = 0; attempt < 64; attempt++) {
        n = put_literal(temp, path);
        n += put_literal(temp + n, ".tmp.");
        n += put_dec(temp + n, sys3(SYS_getpid, 0, 0, 0));
        temp[n++] = '.';
        n += put_dec(temp + n, temp_serial++);
        temp[n] = 0;
        fd = sys3(SYS_open, (long)temp, O_WRONLY | O_CREAT | O_EXCL, 0644);
        if (fd >= 0)
            break;
        if (fd != -EEXIST)
            return 0;
    }
    if (fd < 0)
        return 0;

    while (done < size) {
        long wrote = sys3(SYS_write, fd, (long)data + done, size - done);
        if (wrote <= 0) {
            sys3(SYS_close, fd, 0, 0);
            sys3(SYS_unlink, (long)temp, 0, 0);
            return 0;
        }
        done += wrote;
    }
    if (sys3(SYS_close, fd, 0, 0) != 0 ||
        sys3(SYS_rename, (long)temp, (long)path, 0) != 0) {
        sys3(SYS_unlink, (long)temp, 0, 0);
        return 0;
    }
    return 1;
}

/* Returns bytes read, -2 for a missing file, or -1 for another I/O error. */
static long read_whole_file(const char *path, unsigned char *data, long capacity)
{
    long fd = sys3(SYS_open, (long)path, 0, 0);
    long used = 0;
    if (fd < 0)
        return fd == -ENOENT ? -2 : -1;
    while (used < capacity) {
        long got = sys3(SYS_read, fd, (long)data + used, capacity - used);
        if (got < 0) {
            sys3(SYS_close, fd, 0, 0);
            return -1;
        }
        if (!got) {
            sys3(SYS_close, fd, 0, 0);
            return used;
        }
        used += got;
    }
    sys3(SYS_close, fd, 0, 0);
    return used; /* capacity bytes means oversized or an EOF read was truncated */
}

static long guard_lock(void)
{
    long fd = sys3(SYS_open, (long)GUARD_LOCK_PATH, O_RDWR | O_CREAT, 0644);
    if (fd < 0)
        return -1;
    if (sys3(SYS_flock, fd, LOCK_EX, 0) != 0) {
        sys3(SYS_close, fd, 0, 0);
        return -1;
    }
    return fd; /* close releases the flock */
}

static int guard_write_locked(unsigned long count)
{
    char buf[12];
    int n = put_dec(buf, count);
    buf[n++] = '\n';
    return atomic_write_file(GUARD_PATH, buf, n);
}

static int guard_parse(const unsigned char *buf, long got, unsigned long *out)
{
    unsigned long count = 0;
    long i = 0;
    if (got < 1 || buf[0] < '0' || buf[0] > '9')
        return 0;
    while (i < got && buf[i] >= '0' && buf[i] <= '9') {
        if (count <= GUARD_DISARM)
            count = count * 10 + (buf[i] - '0');
        if (count > GUARD_DISARM)
            count = GUARD_DISARM + 1;
        i++;
    }
    if (i < got && (buf[i] == '\n' || buf[i] == '\r')) {
        char ending = buf[i++];
        if (i < got && ending == '\r' && buf[i] == '\n')
            i++;
    }
    if (i != got)
        return 0;
    *out = count;
    return 1;
}

static int guard_peek(unsigned long *count)
{
    unsigned char buf[16];
    long got = read_whole_file(GUARD_PATH, buf, sizeof(buf));
    return got > 0 && guard_parse(buf, got, count);
}

/* 1 = armed, 0 = temporary failure, -1 = valid disarm threshold reached. */
static int guard_begin(void)
{
    unsigned char buf[16];
    unsigned long count;
    long lock, got;
    struct {
        long sec;
        long nsec;
    } ts;

    if (sys3(SYS_clock_gettime, 1, (long)&ts, 0) != 0)
        return 0;
    lock = guard_lock();
    if (lock < 0)
        return 0;
    got = read_whole_file(GUARD_PATH, buf, sizeof(buf));
    if (got == -2) {
        count = 0; /* first installation only; an existing empty file is malformed */
    } else if (got <= 0 || !guard_parse(buf, got, &count)) {
        sys3(SYS_close, lock, 0, 0);
        return 0;
    }
    if (count >= GUARD_DISARM) {
        sys3(SYS_close, lock, 0, 0);
        return -1;
    }
    if (count >= GUARD_DISARM - 1) {
        int ok = guard_write_locked(GUARD_DISARM);
        sys3(SYS_close, lock, 0, 0);
        return ok ? -1 : 0;
    }
    if (!guard_write_locked(count + 1)) {
        sys3(SYS_close, lock, 0, 0);
        return 0;
    }
    sys3(SYS_close, lock, 0, 0);
    guard_pending = 1;
    guard_clear_after = ts.sec + GUARD_CLEAR_SECONDS;
    return 1;
}

static void warm_parser_init(struct warm_parser *parser)
{
    parser->candidate = 0;
    parser->latest = 0;
    parser->matched = 0;
    parser->digits = 0;
    parser->in_value = 0;
    parser->seen = 0;
}

/* Streaming parser state is the carry for markers split across reads. */
static int warm_parser_feed(struct warm_parser *parser,
                            const unsigned char *data, long size)
{
    static const char prefix[] = "WARM(warm_count=";
    long i;
    for (i = 0; i < size; i++) {
        unsigned char c = data[i];
        if (parser->in_value) {
            if (c >= '0' && c <= '9') {
                unsigned int digit = c - '0';
                if (parser->digits >= 10 || parser->candidate > 429496729U ||
                    (parser->candidate == 429496729U && digit > 5))
                    return 0;
                parser->candidate = parser->candidate * 10 + digit;
                parser->digits++;
            } else if (c == ')' && parser->digits) {
                parser->latest = parser->candidate;
                parser->seen = 1;
                parser->candidate = 0;
                parser->digits = 0;
                parser->in_value = 0;
            } else {
                return 0;
            }
        } else if (parser->matched) {
            if (c == (unsigned char)prefix[parser->matched]) {
                parser->matched++;
                if (!prefix[parser->matched]) {
                    parser->matched = 0;
                    parser->in_value = 1;
                    parser->candidate = 0;
                    parser->digits = 0;
                }
            } else {
                parser->matched = c == 'W' ? 1 : 0;
            }
        } else if (c == 'W') {
            parser->matched = 1;
        }
    }
    return 1;
}

static int warm_parser_finish(const struct warm_parser *parser)
{
    return !parser->matched && !parser->in_value;
}

static int read_boot_uuid(unsigned char boot_id[BOOT_ID_SIZE])
{
    unsigned char data[40];
    long got = read_whole_file(BOOT_ID_PATH, data, sizeof(data));
    int i;
    if (got != BOOT_ID_SIZE && got != BOOT_ID_SIZE + 1 && got != BOOT_ID_SIZE + 2)
        return 0;
    if (got == BOOT_ID_SIZE + 1 && data[BOOT_ID_SIZE] != '\n' &&
        data[BOOT_ID_SIZE] != '\r')
        return 0;
    if (got == BOOT_ID_SIZE + 2 &&
        (data[BOOT_ID_SIZE] != '\r' || data[BOOT_ID_SIZE + 1] != '\n'))
        return 0;
    for (i = 0; i < BOOT_ID_SIZE; i++) {
        unsigned char c = data[i];
        if (i == 8 || i == 13 || i == 18 || i == 23) {
            if (c != '-')
                return 0;
        } else if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') ||
                     (c >= 'A' && c <= 'F'))) {
            return 0;
        }
    }
    for (i = 0; i < BOOT_ID_SIZE; i++)
        boot_id[i] = data[i];
    return 1;
}

static void generation_reader_reset(struct generation_reader *reader, long pid)
{
    if (reader->fd >= 0)
        sys3(SYS_close, reader->fd, 0, 0);
    reader->fd = -1;
    reader->pid = pid;
    reader->offset = 0;
    reader->have_boot_id = 0;
    reader->malformed = 0;
    warm_parser_init(&reader->parser);
}

static int scan_generation(struct generation_reader *reader, struct generation *out)
{
    unsigned char boot_id[BOOT_ID_SIZE];
    unsigned char data[256];
    long pid = sys3(SYS_getpid, 0, 0, 0);
    int i, changed = 0;

    if (!read_boot_uuid(boot_id))
        return 0;
    if (reader->pid != pid)
        generation_reader_reset(reader, pid);
    if (!reader->have_boot_id) {
        changed = 1;
    } else {
        for (i = 0; i < BOOT_ID_SIZE; i++) {
            if (reader->boot_id[i] != boot_id[i]) {
                changed = 1;
                break;
            }
        }
    }
    if (changed) {
        generation_reader_reset(reader, pid);
        for (i = 0; i < BOOT_ID_SIZE; i++)
            reader->boot_id[i] = boot_id[i];
        reader->have_boot_id = 1;
    }
    if (reader->malformed)
        return 0;
    /* Reopen/reseek on every poll: procfs can otherwise keep returning the
     * old EOF forever after new WARM records have been appended. */
    if (reader->fd >= 0)
        sys3(SYS_close, reader->fd, 0, 0);
    reader->fd = sys3(SYS_open, (long)BOOT_LOG_PATH, 0, 0);
    if (reader->fd < 0)
        return 0;
    if (reader->offset > 0 &&
        sys3(SYS_lseek, reader->fd, reader->offset, SEEK_SET) < 0) {
        sys3(SYS_close, reader->fd, 0, 0);
        reader->fd = -1;
        reader->offset = 0;
        return 0;
    }

    for (;;) {
        long got = sys3(SYS_read, reader->fd, (long)data, sizeof(data));
        if (got < 0)
            return 0;
        if (!got)
            break;
        reader->offset += got;
        if (!warm_parser_feed(&reader->parser, data, got)) {
            reader->malformed = 1;
            return 0;
        }
    }
    if (!warm_parser_finish(&reader->parser))
        return 0; /* a partial marker can be completed by a later appended read */
    for (i = 0; i < BOOT_ID_SIZE; i++)
        out->boot_id[i] = reader->boot_id[i];
    out->warm_count = reader->parser.seen ? reader->parser.latest : 0;
    return 1;
}

static int generation_equal(const struct generation *a, const struct generation *b)
{
    int i;
    if (a->warm_count != b->warm_count)
        return 0;
    for (i = 0; i < BOOT_ID_SIZE; i++) {
        if (a->boot_id[i] != b->boot_id[i])
            return 0;
    }
    return 1;
}

static int write_generation(const struct generation *generation)
{
    unsigned char data[GENERATION_SIZE];
    int i;
    for (i = 0; i < BOOT_ID_SIZE; i++)
        data[i] = generation->boot_id[i];
    data[36] = (unsigned char)generation->warm_count;
    data[37] = (unsigned char)(generation->warm_count >> 8);
    data[38] = (unsigned char)(generation->warm_count >> 16);
    data[39] = (unsigned char)(generation->warm_count >> 24);
    return atomic_write_file(GUARD_GEN_PATH, data, sizeof(data));
}

static int invalidate_generation(void)
{
    return atomic_write_file(GUARD_GEN_PATH, "", 0);
}

static int read_generation(struct generation *generation)
{
    unsigned char data[GENERATION_SIZE + 1];
    long got = read_whole_file(GUARD_GEN_PATH, data, sizeof(data));
    int i;
    if (got != GENERATION_SIZE)
        return 0;
    for (i = 0; i < BOOT_ID_SIZE; i++)
        generation->boot_id[i] = data[i];
    generation->warm_count = (unsigned int)data[36] |
                             ((unsigned int)data[37] << 8) |
                             ((unsigned int)data[38] << 16) |
                             ((unsigned int)data[39] << 24);
    return 1;
}

static void log_generation_wait_once(void)
{
    if (!generation_wait_logged) {
        generation_wait_logged = 1;
        log_simple("guard=generation-not-ready");
    }
}

static int publish_generation_if_needed(const struct generation *generation)
{
    struct generation handled;
    if (read_generation(&handled) && generation_equal(&handled, generation))
        return 1;
    return write_generation(generation);
}

static int guard_owner_update(void)
{
    struct generation current;

    if (!scan_generation(&log_reader, &current)) {
        log_generation_wait_once();
        return 0;
    }
    generation_wait_logged = 0;
    if (!guard_generation_known) {
        /* nexhook_init already armed this process: never arm a second time. */
        if (!guard_pending)
            return 0;
        guard_generation = current;
        guard_generation_known = 1;
        if (!write_generation(&current))
            return 0;
        log_simple("guard=init-generation");
        return 1;
    }
    if (!generation_equal(&current, &guard_generation)) {
        int arm = guard_begin();
        if (arm <= 0)
            return arm;
        /* Record locally before publication so a failed write is repaired, not re-armed. */
        guard_generation = current;
        if (!write_generation(&current))
            return 0;
        log_simple("guard=new-warm-generation");
        return 1;
    }
    return publish_generation_if_needed(&current);
}

/* 1 = may continue, 0 = retry later with stock forwarding, -1 = latch disarmed. */
static int guard_runtime_check(void)
{
    struct {
        long sec;
        long nsec;
    } ts;
    unsigned long count;
    long lock;
    int status = 0;

    if (guard_failed)
        return -1;
    if (!recipe_enabled || sys3(SYS_getpid, 0, 0, 0) != guard_owner_pid)
        return 0;
    /* Contention is temporary stock: no clock, reader, counter, or publication work. */
    if (!generation_try_lock())
        return 0;

    if (sys3(SYS_clock_gettime, 1, (long)&ts, 0) != 0)
        goto out;
    /* The poll check/set and compare/arm/publish transition are one critical section. */
    if (!guard_poll_valid || ts.sec != guard_poll_sec) {
        guard_poll_valid = 1;
        guard_poll_sec = ts.sec;
        guard_poll_ok = guard_owner_update();
    }
    if (guard_poll_ok <= 0) {
        status = guard_poll_ok;
        goto out;
    }
    if (!guard_pending) {
        status = 1;
        goto out;
    }
    if (!guard_generation_known)
        goto out; /* do not clear the init arm before its first publication */
    if (ts.sec < guard_clear_after) {
        status = 1;
        goto out;
    }

    lock = guard_lock();
    if (lock < 0)
        goto out;
    if (!guard_peek(&count)) {
        sys3(SYS_close, lock, 0, 0);
        goto out;
    }
    if (count >= GUARD_DISARM) {
        sys3(SYS_close, lock, 0, 0);
        status = -1;
        goto out;
    }
    if (!count) {
        guard_pending = 0;
    } else {
        /* The locked re-read prevents timed clear from overwriting a disarm. */
        if (!guard_write_locked(0)) {
            sys3(SYS_close, lock, 0, 0);
            goto out;
        }
        guard_pending = 0;
    }
    sys3(SYS_close, lock, 0, 0);
    status = 1;
out:
    generation_unlock();
    return status;
}

/* 1 = may modify, 0 = stock until owner handles this generation, -1 = disarm. */
static int guard_target_check(void)
{
    struct generation current, handled;
    unsigned long count;
    int status = 0;

    if (guard_failed)
        return -1;
    /* Also protects the owner generation and every descendant reader access. */
    if (!generation_try_lock())
        return 0;
    if (!guard_peek(&count))
        goto out;
    if (count >= GUARD_DISARM) {
        status = -1;
        goto out;
    }

    if (sys3(SYS_getpid, 0, 0, 0) == guard_owner_pid) {
        if (!guard_generation_known)
            goto out;
        /* The owner scanned at most one second ago in guard_runtime_check. */
        status = publish_generation_if_needed(&guard_generation);
        goto out;
    }

    /* Descendants use their own fd and never arm, clear, or publish. */
    if (!scan_generation(&log_reader, &current)) {
        log_generation_wait_once();
        goto out;
    }
    if (!read_generation(&handled) || !generation_equal(&handled, &current))
        goto out;
    status = 1;
out:
    generation_unlock();
    return status;
}

static int load_config(void)
{
    unsigned char data[CONFIG_SIZE + 1];
    long got = read_whole_file(CONFIG_PATH, data, sizeof(data));
    int i;

    if (got != CONFIG_SIZE || data[0] != 'N' || data[1] != 'X' ||
        data[2] != 'R' || data[3] != '3')
        return 0;

    for (i = 0; i < CONFIG_STYLES; i++) {
        const unsigned char *rec = data + 4 + i * 10;
        signed char sat = (signed char)rec[2];
        signed char hue = (signed char)rec[3];
        signed char lb = (signed char)rec[4];
        signed char cc = (signed char)rec[5];
        signed char wb_lb = (signed char)rec[8];
        signed char wb_cc = (signed char)rec[9];
        if (rec[0] != i || rec[1] >= CONFIG_STYLES ||
            sat < -8 || sat > 7 || hue < -7 || hue > 7 ||
            lb < -9 || lb > 9 || cc < -9 || cc > 9 ||
            (rec[6] >= CONFIG_STYLES && rec[6] != 0xff) || rec[7] > 100 ||
            wb_lb < -9 || wb_lb > 9 || wb_cc < -9 || wb_cc > 9)
            return 0;
        recipes[i].base = rec[1];
        recipes[i].sat = sat;
        recipes[i].hue = hue;
        recipes[i].lb = lb;
        recipes[i].cc = cc;
        recipes[i].wb_mode = rec[6];
        recipes[i].wb_temp = rec[7];
        recipes[i].wb_lb = wb_lb;
        recipes[i].wb_cc = wb_cc;
    }
    return 1;
}

static int write_state(unsigned char style)
{
    return atomic_write_file(STATE_PATH, &style, 1);
}

static int read_state(void)
{
    unsigned char data[2];
    if (read_whole_file(STATE_PATH, data, sizeof(data)) != 1)
        return -1;
    return data[0];
}

static void disarm_all(void)
{
    long lock;
    guard_failed = 1;
    recipe_enabled = 0;
    guard_pending = 0;
    lock = guard_lock();
    if (lock < 0)
        return; /* this process is still latched off; never write outside the lock */
    guard_write_locked(GUARD_DISARM);
    write_state(STATE_DISARMED);
    sys3(SYS_close, lock, 0, 0);
}

static void log_state_error_once(void)
{
    if (!state_error_logged) {
        state_error_logged = 1;
        log_simple("error=style-state");
    }
}

static int ensure_apis(void)
{
    if (api_failed)
        return 0;
    if (!real_valloc_msg_wait)
        real_valloc_msg_wait = (valloc_msg_fn)dlsym(RTLD_NEXT,
                                                    "osal_valloc_msg_wait");
    if (!real_free_msg)
        real_free_msg = (free_msg_fn)dlsym(RTLD_NEXT, "osal_free_msg");
    if (!real_backup_read)
        real_backup_read = (backup_read_fn)dlsym(RTLD_NEXT, "Backup_read");
    if (!real_valloc_msg_wait || !real_free_msg || !real_backup_read) {
        api_failed = 1;
        if (!api_error_logged) {
            api_error_logged = 1;
            log_simple("error=dlsym-osal-alloc-free");
        }
        return 0;
    }
    return 1;
}

static void fill_profile_values(unsigned char *msg, const struct recipe *recipe)
{
    int i;
    for (i = 0; i < PROFILE_VALUES; i++)
        msg[8 + i] = (unsigned char)neutral_profile[i];
    msg[8 + 2] = (unsigned char)recipe->lb;
    msg[8 + 3] = (unsigned char)recipe->cc;
    msg[8 + 13] = (unsigned char)recipe->sat;
    msg[8 + 14] = (unsigned char)recipe->hue;
}

static long prepare_profile(const struct recipe *recipe, unsigned char **out)
{
    unsigned char *msg = 0;
    long rc;
    *out = 0;
    rc = real_valloc_msg_wait(CAMERA_CORE_MAILBOX, (void **)&msg,
                              PROFILE_SIZE, 1);
    if (rc != 0 || !msg)
        return rc ? rc : -1;

    msg[0] = 0x05;
    msg[1] = 0x00;
    msg[2] = 0x66;
    msg[3] = 0x40;
    msg[4] = msg[5] = msg[6] = msg[7] = 0;
    msg[-4] = msg[-3] = msg[-2] = msg[-1] = 0; /* source ID: scenario-compatible 0 */
    fill_profile_values(msg, recipe);
    *out = msg;
    return 0;
}

static void capture_wb_template(const unsigned char *msg)
{
    int i;
    for (i = 0; i < WB_MESSAGE_SIZE; i++)
        wb_template[i] = msg[i];
    wb_template_valid = 1;
}

static int read_wb_template(void)
{
    unsigned char mode, lb, cc, temp, daylight;
    if (!real_backup_read)
        return 0;
    if (real_backup_read(WB_STORE_MODE, &mode) < 0 ||
        real_backup_read(WB_STORE_ADJUST_LB, &lb) < 0 ||
        real_backup_read(WB_STORE_ADJUST_CC, &cc) < 0 ||
        real_backup_read(WB_STORE_COLOR_TEMP, &temp) < 0 ||
        real_backup_read(WB_STORE_DAYLIGHT_LEVEL, &daylight) < 0)
        return 0;
    if (mode >= CONFIG_STYLES)
        return 0;
    wb_template[0] = 0x05;
    wb_template[1] = 0x00;
    wb_template[2] = 0x0c;
    wb_template[3] = 0x40;
    wb_template[4] = wb_template[5] = wb_template[6] = wb_template[7] = 0;
    wb_template[8] = mode;
    wb_template[9] = lb;
    wb_template[10] = cc;
    wb_template[11] = temp;
    wb_template[12] = daylight;
    wb_template_valid = 1;
    return 1;
}

static long prepare_wb(const struct recipe *recipe, unsigned char **out)
{
    unsigned char *msg = 0;
    long rc;
    int i;
    *out = 0;
    rc = real_valloc_msg_wait(CAMERA_CORE_MAILBOX, (void **)&msg,
                              WB_MESSAGE_SIZE, 1);
    if (rc != 0 || !msg)
        return rc ? rc : -1;
    for (i = 0; i < WB_MESSAGE_SIZE; i++)
        msg[i] = wb_template[i];
    msg[8] = recipe->wb_mode;
    if (recipe->wb_temp)
        msg[11] = recipe->wb_temp; /* unsigned Kelvin/100 */
    msg[9] = (unsigned char)recipe->wb_lb;
    msg[10] = (unsigned char)recipe->wb_cc;
    msg[-4] = msg[-3] = msg[-2] = msg[-1] = 0;
    *out = msg;
    return 0;
}

static void capture_wb_if_valid(unsigned char *msg, unsigned int id)
{
    unsigned char *record = id == MSG_INIT_SETTINGS ? msg + WB_INIT_OFFSET : msg;
    if (record[0] == 0x05 && record[2] == 0x0c && record[3] == 0x40 &&
        record[8] < CONFIG_STYLES)
        capture_wb_template(record);
}

static void handle_outgoing_wb(unsigned char *msg, unsigned int id)
{
    unsigned char *record = id == MSG_INIT_SETTINGS ? msg + WB_INIT_OFFSET : msg;
    int style;
    if (record[0] != 0x05 || record[2] != 0x0c || record[3] != 0x40 ||
        record[8] >= CONFIG_STYLES)
        return;
    capture_wb_template(record);
    style = read_state();
    if (style < 0 || style >= CONFIG_STYLES || recipes[style].wb_mode == 0xff)
        return;
    record[8] = recipes[style].wb_mode;
    if (recipes[style].wb_temp)
        record[11] = recipes[style].wb_temp;
    record[9] = (unsigned char)recipes[style].wb_lb;
    record[10] = (unsigned char)recipes[style].wb_cc;
    log_wb_rewrite((unsigned char)style, record[8]);
}

static long handle_style(snd_msg_fn real, unsigned long mailbox, unsigned char *msg)
{
    unsigned char selected = msg[8];
    unsigned char *prepared;
    unsigned char *prepared_wb = 0;
    struct recipe recipe;
    int previous;
    long style_rc, pp_rc, wb_rc = 0;

    if (selected >= CONFIG_STYLES)
        return real(mailbox, msg);
    previous = read_state();
    if (previous == STATE_DISARMED)
        return real(mailbox, msg);
    if (previous < 0 || (previous >= CONFIG_STYLES && previous != STATE_UNKNOWN)) {
        log_state_error_once();
        return real(mailbox, msg);
    }

    recipe = recipes[selected];
    if (recipe.wb_mode != 0xff && !wb_template_valid && !read_wb_template()) {
        log_wb_action(&recipe, -2); /* no valid WB fields: no partial recipe */
        return real(mailbox, msg);
    }
    pp_rc = prepare_profile(&recipe, &prepared);
    if (pp_rc != 0) {
        log_style_action(selected, recipe.base, -1, pp_rc);
        return real(mailbox, msg); /* no allocation: leave the style completely stock */
    }
    if (recipe.wb_mode != 0xff && wb_template_valid) {
        wb_rc = prepare_wb(&recipe, &prepared_wb);
        if (wb_rc != 0) {
            real_free_msg(mailbox, prepared);
            log_wb_action(&recipe, wb_rc);
            return real(mailbox, msg); /* WB allocation failed: keep the style stock */
        }
    }
    if (!write_state((unsigned char)selected)) {
        real_free_msg(mailbox, prepared);
        if (prepared_wb)
            real_free_msg(mailbox, prepared_wb);
        log_state_error_once();
        disarm_all();
        log_style_action(selected, recipe.base, -1, -1);
        return real(mailbox, msg);
    }

    if (prepared_wb) {
        wb_rc = real(mailbox, prepared_wb); /* WB ownership transfers on send */
        log_wb_action(&recipe, wb_rc);
        if (wb_rc != 0) {
            real_free_msg(mailbox, prepared);
            disarm_all();
            log_style_action(selected, recipe.base, -1, wb_rc);
            return wb_rc;
        }
    }
    msg[8] = recipe.base;
    style_rc = real(mailbox, msg);
    if (style_rc != 0) {
        if (!write_state((unsigned char)previous))
            disarm_all();
        if (prepared_wb)
            disarm_all(); /* WB was already applied, so do not continue partial recipes */
        real_free_msg(mailbox, prepared); /* never passed to osal_snd_msg */
        log_style_action(selected, recipe.base, style_rc, -1);
        return style_rc;
    }

    pp_rc = real(mailbox, prepared); /* ownership transferred; never free after this */
    if (pp_rc != 0)
        disarm_all(); /* a partial recipe must not lead to later mismatched rewrites */
    log_style_action(selected, recipe.base, style_rc, pp_rc);
    return style_rc;
}

static long handle_outgoing_profile(snd_msg_fn real, unsigned long mailbox,
                                    unsigned char *msg)
{
    int style = read_state();
    if (style < 0) {
        log_state_error_once();
        return real(mailbox, msg);
    }
    if (style >= CONFIG_STYLES)
        return real(mailbox, msg); /* unknown or disarmed: preserve the app's PP */
    fill_profile_values(msg, &recipes[style]);
    log_pp_rewrite((unsigned char)style);
    return real(mailbox, msg);
}

int nexhook_is_im(void)
{
    return process_is_im;
}

int osal_snd_msg(unsigned long mailbox, void *message)
{
    unsigned char *msg = (unsigned char *)message;
    snd_msg_fn real = real_snd_msg;
    unsigned int id;
    int guard_status;

    if (!real) {
        real = (snd_msg_fn)dlsym(RTLD_NEXT, "osal_snd_msg");
        if (!real) {
            if (process_is_im && !resolve_error_logged) {
                resolve_error_logged = 1;
                log_simple("error=dlsym-osal_snd_msg");
            }
            return -1;
        }
        real_snd_msg = real;
    }

    if (process_is_im && recipe_enabled &&
        sys3(SYS_getpid, 0, 0, 0) == guard_owner_pid) {
        guard_status = guard_runtime_check();
        if (guard_status < 0)
            disarm_all();
        if (guard_status <= 0)
            return real(mailbox, message);
    }
    if (!recipe_enabled || !msg)
        return real(mailbox, message);

    id = msg[2] | ((unsigned int)msg[3] << 8);
    if (mailbox != CAMERA_CORE_MAILBOX)
        return real(mailbox, message);
    if (id == MSG_WB_MODE_CMD || id == MSG_INIT_SETTINGS)
        capture_wb_if_valid(msg, id); /* read-only capture is always stock-safe */
    if (id != MSG_COLOR_MODE && id != MSG_PICTURE_PROFILE &&
        id != MSG_WB_MODE_CMD && id != MSG_INIT_SETTINGS)
        return real(mailbox, message);
    guard_status = guard_target_check();
    if (guard_status < 0)
        disarm_all();
    if (guard_status <= 0)
        return real(mailbox, message);
    if (id == MSG_WB_MODE_CMD || id == MSG_INIT_SETTINGS) {
        handle_outgoing_wb(msg, id);
        return real(mailbox, message);
    }
    if (!ensure_apis())
        return real(mailbox, message);
    if (id == MSG_COLOR_MODE)
        return handle_style(real, mailbox, msg);
    return handle_outgoing_profile(real, mailbox, msg);
}

void nexhook_init(void)
{
    static const char target[] = "im.elf";
    char cmdline[160];
    long fd, got, i;
    int match = 1;
    int arm;

    recipe_enabled = 0;
    process_is_im = 0;
    generation_gate = 0;
    generation_gate_pid = sys3(SYS_getpid, 0, 0, 0);
    log_reader.fd = -1;
    log_reader.pid = -1;
    fd = sys3(SYS_open, (long)"/proc/self/cmdline", 0, 0);
    if (fd < 0)
        return;
    got = sys3(SYS_read, fd, (long)cmdline, sizeof(cmdline));
    sys3(SYS_close, fd, 0, 0);
    if (got <= 0)
        return;

    for (i = 0; i < (long)sizeof(target); i++) {
        if (i >= got || cmdline[i] != target[i]) {
            match = 0;
            break;
        }
    }
    if (!match) {
        log_init_record("inactive", cmdline, got);
        return;
    }

    process_is_im = 1;
    guard_owner_pid = sys3(SYS_getpid, 0, 0, 0);
    guard_generation_known = 0;
    guard_pending = 0;
    guard_failed = 0;
    guard_poll_valid = 0;
    if (!load_config()) {
        log_init_record("disarmed-config", cmdline, got);
        return;
    }
    if (!write_state(STATE_UNKNOWN)) {
        log_init_record("disabled-state-temporary", cmdline, got);
        return;
    }

    recipe_enabled = 1;
    arm = guard_begin();
    if (arm < 0) {
        disarm_all();
        log_init_record("disarmed-guard", cmdline, got);
        return;
    }
    if (!arm) {
        recipe_enabled = 0;
        log_init_record("disabled-guard-temporary", cmdline, got);
        return;
    }
    if (!invalidate_generation()) { /* invalid until owner publishes exact 40 bytes */
        recipe_enabled = 0;
        log_init_record("disabled-generation-temporary", cmdline, got);
        return;
    }
    log_init_record("active", cmdline, got);
}
